"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[55045],{55045:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/just-one-more-lie.png\\"\\n          title=\\"거짓말 딱 한개만 더\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"현대문학\\"\\n          publishedDate=\\"2009-07-27\\"\\n          isbn=\\"9788972754404\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n이 작품은 다섯 편의 단편집이며, 각각 독립된 사건을 다루지만, <mark>거짓말</mark>이라는 행위를 통해 발현되는 인간 본성의 다양한 측면을 보여준다.  \\n<br>\\n```가가 형사``` 시리즈 중 유일한 단편집이라고 한다.  \\n<br>\\n작품에 등장하는 범인들은 저마다의 절박한 이유로 진실을 은폐하고, 그 위에 또 다른 거짓을 쌓아올리며 위태로운 성벽을 구축한다.  \\n<br>\\n가가 형사는 이 견고해 보이는 거짓의 성벽에 미세한 균열을 찾아내고, 결정적인 쐐기를 박는다.  \\n범인을 심리적으로 압박하여 결국 <mark>거짓말을 딱 한 개만 더 하도록 유도</mark>하는 고도의 심리전을 펼친다.  \\n<br>\\n이 과정에서 드러나는 인간의 나약함, 뒤틀린 욕망, 숭고하지만 비극적인 사랑, 그리고 죄책감의 무게는 이 작품의 핵심적인 재미와 주제이다.  "}')}}]);